/* Reviewed Round24 evidence; previous rounds remain accessible as archives. */
(() => {
  'use strict';
  const prior=window.ResearchObservatory,D=window.ROUND24_DATA;
  const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const route=(id,label)=>`<a href="#research/${id}">${esc(label)}</a>`;
  const source=(p,label)=>`<a href="https://github.com/occult-kranti/yang_mills_workbench/blob/main/${esc(p)}">${esc(label)} ↗</a>`;
  const nav=()=>`<nav class="rc-nav" aria-label="Round24 navigation">${route('home','Current findings')}${route('round24-roadmap','Roadmap & handoff')}${route('research-methods','Newton & Tesla')}${route('round23-home','Round23 archive')}</nav>`;
  const status=x=>x.verdict==='accepted_within_scope'?'Accepted within scope':x.verdict==='limited'?'Limited target':'Insufficient for target';
  const evidence=x=>`<div class="r22-evidence">${['contracts','forward','reverse','skeptic','advisor'].map((d,i)=>source(`research/round24/${d}/${d==='contracts'?x.loop+'.json':d==='skeptic'?x.loop+'-review.md':d==='advisor'?x.loop+'-gate.json':x.loop+'/report.md'}`,['Contract','Forward proof','Reverse proof','Skeptic review','Evidence gate'][i])).join('')}</div>`;
  const card=x=>`<article class="rc-result"><p class="rc-kicker">${esc(x.loop.toUpperCase())} · ${esc(status(x))}</p><h2>${esc(x.title)}</h2><p>${esc(x.statement)}</p>${route('round24-'+x.loop,'Equations, review and limits →')}</article>`;
  function home(){return `<section class="rc-hero"><div><p class="rc-kicker">Round24 · five goal pairs</p><h1>What survives measurement, filtering and truncation?</h1><p>Ten new investigations follow the endpoint result. Each second round responds to the first round’s skeptical review. The final two goals were selected after the first three pairs.</p><div class="rc-hero-actions">${route('round24-v1','Start with the observable →')}${route('round24-roadmap','Read the handoff →')}</div></div><aside class="rc-score"><span class="rc-score-number">${D.loops.length}<span>/ 10</span></span><strong>New investigations reviewed</strong><small>This counts work completed, not the fraction of Yang–Mills solved.</small></aside></section><section class="r23-disclosure"><strong>Separate forward, reverse and skeptic agents; one integrating advisor.</strong><p>Newton’s analysis/synthesis and Tesla’s mechanism/loading methods guide the questions. Historical analogy supplies no theorem premises. Scientific priority is unverified; the four-dimensional continuum problem remains open.</p></section><section class="rc-section"><h2>Contributions in this round</h2><p>${esc(D.summary)}</p><p>Each result below names its model and its remaining limitation. Exact algebraic checks support the written arguments; they are not simulated infinite-system trajectories.</p></section><div class="rc-results rc-results-all">${D.loops.map(card).join('')}</div><section class="r22-limit"><h2>Still open</h2><ul>${D.open_goals.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`;}
  function loopPage(x){return `<header class="r22-page-head"><p class="rc-kicker">${esc(x.loop.toUpperCase())} · ${esc(status(x))}</p><h1>${esc(x.title)}</h1><p>${esc(x.model)}</p></header><section class="rc-section"><h2>Supported statement</h2><p>${esc(x.statement)}</p>${x.equations.map(e=>`<div class="r22-formula">${esc(e)}</div>`).join('')}<h2>What changed after review</h2><p>${esc(x.feedback)}</p><h2>Scope and limits</h2><ul>${x.limits.map(l=>`<li>${esc(l)}</li>`).join('')}</ul>${x.loop==='w1'?'<figure><img src="round24-residual-bound.svg" alt="Analytic lower factor of the retained S source residual across the permitted filter interval" style="width:100%;height:auto"><figcaption>The curves are certified lower factors. They are not measurements or simulated dynamics.</figcaption></figure>':''}${evidence(x)}<code class="r22-hash">Gate SHA-256: ${esc(x.gate_sha256)}</code><details class="r23-proof"><summary>Read the forward derivation</summary><article class="r23-essay">${x.forward_html}</article></details><details class="r23-proof"><summary>Read the independent reverse reconstruction</summary><article class="r23-essay">${x.reverse_html}</article></details><details class="r23-proof"><summary>Read the skeptical review</summary><article class="r23-essay">${x.review_html}</article></details><h2>Reproduce</h2><pre>python3 -B research/round24/admission.py --loops ${esc(x.loop)} --output /absolute/new/${esc(x.loop)}</pre><p>Independent model-agent review is not external mathematical peer review. Scientific priority remains unverified.</p></section>`;}
  function roadmap(){return `<header class="r22-page-head"><p class="rc-kicker">Ten new research rounds</p><h1>This cycle is complete.</h1><p>V/W continue the handoff. X addresses its listed truncation problem. Y/Z were selected from the first three reviewed pairs. Further research is planned and unexecuted.</p></header><section class="rc-section"><div class="r23-table-wrap"><table class="r23-table"><thead><tr><th>Loop</th><th>Target</th><th>Verdict</th></tr></thead><tbody>${D.loops.map(x=>`<tr><th>${route('round24-'+x.loop,x.loop.toUpperCase())}</th><td>${esc(x.title)}</td><td>${esc(status(x))}</td></tr>`).join('')}</tbody></table></div><h2>Next missing premises</h2><ul>${D.open_goals.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${source('research/round24/HANDOFF.md','Current handoff')} · ${source('research/round24/advisor/roadmap.json','Research roadmap')} · ${source('research/round24/NOVELTY.md','Novelty and closest prior work')}</section>`;}
  function render(r='home'){
    if(r==='round23-home')return `<div class="rc-history-notice">Historical six-loop checkpoint. ${route('home','Current Round24 findings →')}</div>`+prior.render('home');
    if(r==='round23-roadmap')return `<div class="rc-history-notice">Historical stop boundary, superseded by the new instruction. ${route('round24-roadmap','Current roadmap →')}</div>`+prior.render(r);
    const x=D.loops.find(x=>r==='round24-'+x.loop);
    if(!['home','contributions','round24-roadmap'].includes(r)&&!x)return prior.render(r);
    return `<div class="rc20 r21 r22 r23 r24">${nav()}${x?loopPage(x):r==='round24-roadmap'?roadmap():home()}<footer class="rc-footer"><strong>Yang–Mills Workbench · Round24</strong>${source('research/round24/HANDOFF.md','Handoff')}</footer></div>`;
  }
  function afterRender(){const r=location.hash.split('/')[1]||'home';if(r==='home'||r==='contributions'||r.startsWith('round24-')){window.ResearchJourney?.cleanup?.();document.title='Round24 · Research findings · Yang–Mills Workbench';}else prior.afterRender();}
  window.ResearchRound24={render,afterRender,data:D};window.ResearchObservatory={...prior,render,afterRender};
})();
